 strategy is based on absolute detection of a fire (when the fire strength is sufficient to detect), and on detection relative to its background (to account for variability of the surface temperature and reflection by sunlight). Numerous tests are employed to reject typical false alarm sources like sun glint or an unmasked coastline.MOD14 is level-2 swath data provided daily at 1-kilometer resolution. The Science Data Sets in this product include fire-mask, algorithm quality, radiative power, and numerous layers describing fire pixel attributes. The Terra MODIS instrument acquires data twice daily (10:30 AM and PM), as does the Aqua MODIS (1:30 PM and AM). These four daily MODIS fire observations serve to advance global monitoring of the fire process and its effects on ecosystems, the atmosphere, and climate.","service_features":{"opendap":{"has_formats":false,"has_variables":false,"has_transforms":false,"has_combine":false,"has_spatial_subsetting":false,"has_temporal_subsetting":false},"esi":{"has_formats":false,"has_variables":false,"has_transforms":false,"has_combine":false,"has_spatial_subsetting":false,"has_temporal_subsetting":false},"harmony":{"has_formats":false,"has_variables":false,"has_transforms":false,"has_combine":false,"has_spatial_subsetting":false,"has_temporal_subsetting":false}},"orbit_parameters":{},"id":"C2007630683-LANCEMODIS","has_formats":false,"consortiums":["EOSDIS","GEOSS"],"original_format":"UMM_JSON","collection_data_type":"NEAR_REAL_TIME","has_temporal_subsetting":false,"browse_flag":false,"platforms":["Terra"],"association_details":{"visualizations":[{"concept_id":"VIS4294089021-ESDIS"},{"concept_id":"VIS4294089033-ESDIS"},{"concept_id":"VIS4294089038-ESDIS"},{"concept_id":"VIS4294089014-ESDIS"},{"concept_id":"VIS4294089031-ESDIS"},{"concept_id":"VIS4294089017-ESDIS"}],"citations":[{"concept_id":"CIT3804153502-ESDIS"}]},"online_access_flag":true,"links":[{"rel":"http://esipfed.org/ns/fedsearch/1.1/metadata#","hreflang":"en-US","href":"